package com.smartapproval.service;
import com.smartapproval.domain.*; import com.smartapproval.dto.*; import com.smartapproval.exception.*; import com.smartapproval.repository.PurchaseRequestRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.Instant; import java.util.*;
@Service @Transactional public class PurchaseRequestService {
 private static final BigDecimal AUTO_LIMIT=new BigDecimal("1000000"); private final PurchaseRequestRepository repo; public PurchaseRequestService(PurchaseRequestRepository repo){this.repo=repo;}
 public PurchaseRequestResponse create(CreatePurchaseRequest d){var status=d.amount().compareTo(AUTO_LIMIT)<=0?RequestStatus.APROBADA:RequestStatus.PENDIENTE;var p=new PurchaseRequest(UUID.randomUUID(),d.requesterName().trim(),d.requesterEmail().trim().toLowerCase(),d.concept().trim(),d.description().trim(),d.amount(),d.costCenter().trim(),status,Instant.now());return PurchaseRequestMapper.toResponse(repo.save(p));}
 @Transactional(readOnly=true) public List<PurchaseRequestResponse> list(RequestStatus status,String search){String q=search==null||search.isBlank()?null:search.trim();List<PurchaseRequest> results;if(status==null&&q==null)results=repo.findAllByOrderByCreatedAtDesc();else if(status!=null&&q==null)results=repo.findByStatusOrderByCreatedAtDesc(status);else if(status==null)results=repo.findByRequesterNameContainingIgnoreCaseOrConceptContainingIgnoreCaseOrderByCreatedAtDesc(q,q);else results=repo.findByStatusAndRequesterNameContainingIgnoreCaseOrStatusAndConceptContainingIgnoreCaseOrderByCreatedAtDesc(status,q,status,q);return results.stream().map(PurchaseRequestMapper::toResponse).toList();}
 @Transactional(readOnly=true) public PurchaseRequestResponse get(UUID id){return PurchaseRequestMapper.toResponse(find(id));}
 public PurchaseRequestResponse approve(UUID id,String comment){var p=find(id);ensurePending(p);p.decide(RequestStatus.APROBADA,comment);return PurchaseRequestMapper.toResponse(p);}
 public PurchaseRequestResponse reject(UUID id,String comment){var p=find(id);ensurePending(p);p.decide(RequestStatus.RECHAZADA,comment.trim());return PurchaseRequestMapper.toResponse(p);}
 @Transactional(readOnly=true) public MetricsResponse metrics(){var all=repo.findAll();return new MetricsResponse(all.size(),all.stream().filter(p->p.getStatus()==RequestStatus.PENDIENTE).count(),all.stream().filter(p->p.getStatus()==RequestStatus.APROBADA).count(),all.stream().filter(p->p.getStatus()==RequestStatus.RECHAZADA).count(),all.stream().map(PurchaseRequest::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add));}
 private PurchaseRequest find(UUID id){return repo.findById(id).orElseThrow(NotFoundException::new);} private void ensurePending(PurchaseRequest p){if(p.getStatus()!=RequestStatus.PENDIENTE)throw new InvalidDecisionException();}
}
